(()=>{'use strict';
const P=window.CosmologyPhysics,$=id=>document.getElementById(id),colors=window.BookTheme.palette({r:'#7abdc4',m:'#e4c389',l:'#b5cebb'}),key='galaxies-chapter-3-labs';
const state={a:.5,observer:0,h0:70,matter:.3,epoch:0,z:2,kind:'all',thermal:0,w:-1,N:3};
try{const saved=JSON.parse(localStorage.getItem(key)||'{}');for(const [k,min,max] of [['a',.2,1],['observer',0,2],['h0',50,90],['matter',.1,.9],['epoch',-5,Math.log10(2)],['z',.01,10],['thermal',0,4],['w',-1,.34],['N',0,6]])if(typeof saved[k]==='number'&&Number.isFinite(saved[k]))state[k]=Math.max(min,Math.min(max,saved[k]));if(['all','dc','da','dl'].includes(saved.kind))state.kind=saved.kind;state.observer=Math.round(state.observer);state.thermal=Math.round(state.thermal);}catch{}
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{}}
const fmt=(n,d=2)=>n.toLocaleString('zh-CN',{maximumFractionDigits:d,minimumFractionDigits:d});
const ageText=n=>n<1e-6?fmt(n*1e9,1)+' 年':n<.001?fmt(n*1e6,1)+' 千年':n<1?fmt(n*1000,1)+' 百万年':fmt(n,2)+' Gyr';
let model=P.model(state.h0,state.matter),distanceSeries=[];
const bind=(id,k,fn)=>{$(id).addEventListener('input',e=>{state[k]=Number(e.target.value);save();fn();});};
for(const [id,k] of [['scale-factor','a'],['cosmo-h0','h0'],['cosmo-matter','matter'],['cosmo-epoch','epoch'],['distance-z','z'],['fluid-w','w'],['efolds','N']])$(id).value=state[k];$('distance-kind').value=state.kind;
const animations=new Map();
function stop(id){const run=animations.get(id);if(run)cancelAnimationFrame(run.frame);animations.delete(id);$(id).textContent=id==='expansion-play'?'播放膨胀':'播放尺度变化';$(id).setAttribute('aria-pressed','false');if(id==='inflation-play')$('inflation-result').setAttribute('aria-live','polite');save();}
function animate(id,k,input,end,begin,duration,render){if(animations.has(id)){stop(id);return;}if(state[k]>=end-.001)state[k]=begin;const from=state[k],start=performance.now();const run={frame:0};animations.set(id,run);$(id).textContent='暂停';$(id).setAttribute('aria-pressed','true');if(id==='inflation-play')$('inflation-result').setAttribute('aria-live','off');function frame(now){const t=Math.min(1,(now-start)/duration);state[k]=from+(end-from)*t;$(input).value=state[k];render();if(t<1)run.frame=requestAnimationFrame(frame);else{stop(id);$(id).textContent='重新播放';}}run.frame=requestAnimationFrame(frame);}
document.addEventListener('visibilitychange',()=>{if(document.hidden)for(const id of [...animations.keys()])stop(id);});
function canvas(id){const c=$(id),r=c.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);c.width=Math.round(r.width*dpr);c.height=Math.round(r.height*dpr);const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);return {c,ctx,w:r.width,h:r.height};}
function expansion(){const x=P.expansion(state.a);$('scale-large').textContent=fmt(state.a);$('scale-value').textContent='a = '+fmt(state.a,3);$('expansion-z').textContent='z = '+fmt(x.z);$('grid-separation').innerHTML=fmt(x.separation,1)+' <small>Mpc</small>';$('wave-ratio').textContent='× '+fmt(x.wavelengthRatio);document.querySelectorAll('[data-observer]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.observer===state.observer)));
 const {c,ctx,w,h}=canvas('expansion-canvas'),base=Math.min(w/5.5,h/3.8),s=base*state.a,cx=w/2,cy=h*.57,observers=[[0,0],[1.5,0],[-1.5,1.5]],o=observers[state.observer];ctx.strokeStyle=window.BookTheme.color('#28414b');ctx.lineWidth=.6;
 for(let i=-30;i<=30;i++){const px=cx+(i-o[0])*s,py=cy+(i-o[1])*s;ctx.beginPath();ctx.moveTo(px,70);ctx.lineTo(px,h-40);ctx.stroke();ctx.beginPath();ctx.moveTo(0,py);ctx.lineTo(w,py);if(py>70&&py<h-40)ctx.stroke();}
 ctx.save();ctx.beginPath();ctx.rect(0,85,w,h-125);ctx.clip();for(let j=-12;j<=12;j++)for(let i=-12;i<=12;i++){const px=cx+(i*1.5-o[0])*s,py=cy+(j*1.5-o[1])*s;if(px<0||px>w||py<80||py>h-35)continue;ctx.save();ctx.translate(px,py);ctx.rotate(((i*7+j*3)%11)/6);const grad=ctx.createRadialGradient(0,0,0,0,0,9);grad.addColorStop(0,window.BookTheme.color('#ebdab2'));grad.addColorStop(.2,window.BookTheme.color('#a0baba'));grad.addColorStop(1,window.BookTheme.color('#7abdc400'));ctx.scale(1,.45);ctx.fillStyle=grad;ctx.beginPath();ctx.arc(0,0,9,0,Math.PI*2);ctx.fill();ctx.restore();}
 observers.forEach((v,i)=>{const px=cx+(v[0]-o[0])*s,py=cy+(v[1]-o[1])*s;ctx.strokeStyle=i===state.observer?colors.m:window.BookTheme.color('#657f82');ctx.setLineDash(i===state.observer?[]:[3,3]);ctx.lineWidth=1;ctx.beginPath();ctx.arc(px,py,12,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=i===state.observer?colors.m:window.BookTheme.color('#a1b8ba');ctx.font='11px -apple-system,sans-serif';ctx.fillText(String.fromCharCode(65+i),px-3,py-18);});ctx.restore();
 ctx.strokeStyle=window.BookTheme.color('#92a9aa');ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(20,h-21);ctx.lineTo(20+base,h-21);ctx.moveTo(20,h-25);ctx.lineTo(20,h-17);ctx.moveTo(20+base,h-25);ctx.lineTo(20+base,h-17);ctx.stroke();ctx.fillStyle=window.BookTheme.color('#98aeae');ctx.font='10px -apple-system,sans-serif';ctx.fillText('100 Mpc 固有长度',25+base,h-17);c.setAttribute('aria-label',`a=${fmt(state.a)}，一格固有间隔 ${fmt(x.separation)} Mpc，共动间隔100 Mpc；以星系${'ABC'[state.observer]}为观测者。`);
 for(const [id,ratio,color] of [['wave-emitted',1,colors.r],['wave-observed',x.wavelengthRatio,colors.m]]){const width=$(id).clientWidth;const points=d3.range(0,width+1,2).map(t=>[t,21+13*Math.sin(t/(18*ratio)*Math.PI*2)]);const svg=d3.select('#'+id).attr('viewBox',`0 0 ${width} 42`);svg.selectAll('*').remove();svg.append('path').attr('d',d3.line()(points)).attr('stroke',color).attr('stroke-width',1.5).attr('fill','none');}
}
bind('scale-factor','a',()=>{stop('expansion-play');expansion();});document.querySelectorAll('[data-observer]').forEach(b=>b.addEventListener('click',()=>{state.observer=+b.dataset.observer;save();expansion();}));$('expansion-play').addEventListener('click',()=>animate('expansion-play','a','scale-factor',1,.2,9000,expansion));
function plot(id,xScale,yScale,xTitle,yTitle,yTicks=5){return window.BookCharts.frame(id,{x:xScale,y:yScale,xLabel:xTitle,yLabel:yTitle});}
function vertical(p,x){p.svg.append('line').attr('x1',x).attr('x2',x).attr('y1',p.m.top).attr('y2',p.h-p.m.bottom).attr('stroke',window.BookTheme.color('#e8dfc9')).attr('stroke-width',1).attr('stroke-dasharray','4 4');}
function components(){const a=10**state.epoch,c=P.components(a,model);$('h0-value').textContent=fmt(state.h0,0)+' km/s/Mpc';$('matter-value').textContent=fmt(state.matter);$('model-closure').textContent=`平直模型：Ωᵣ,₀ = 0.00009，ΩΛ,₀ = ${fmt(model.l,5)}。下方距离实验共用这些参数。`;$('epoch-value').textContent='a = '+(a<.01?a.toExponential(2):fmt(a,3))+(a<=1?' · z = '+fmt(1/a-1,1):' · 未来');$('epoch-h').textContent=c.H>10000?c.H.toExponential(2):fmt(c.H,1);$('epoch-age').textContent=ageText(P.age(a,model));$('epoch-q').textContent=fmt(c.q,3);$('component-note').textContent=`所选时代：辐射 ${fmt(c.r*100,1)}%，物质 ${fmt(c.m*100,1)}%，宇宙学常数 ${fmt(c.l*100,1)}%。${c.q<0?'此时加速膨胀（q<0）。':'此时减速膨胀（q≥0）。'}`;
 const p=plot('component-chart',d3.scaleLinear().domain([-5,Math.log10(2)]),d3.scaleLinear().domain([0,100]),'log₁₀ a（0 表示今天）','占总密度 / %'),data=d3.range(241).map(i=>{const x=-5+i/240*(5+Math.log10(2)),v=P.components(10**x,model);return {x,r:v.r*100,m:v.m*100,l:v.l*100};});d3.stack().keys(['r','m','l'])(data).forEach(layer=>p.svg.append('path').datum(layer).attr('d',d3.area().x(d=>p.x(d.data.x)).y0(d=>p.y(d[0])).y1(d=>p.y(d[1]))).attr('fill',colors[layer.key]).attr('fill-opacity',.45).attr('stroke',colors[layer.key]).attr('stroke-width',.8));vertical(p,p.x(state.epoch));p.svg.append('line').attr('x1',p.x(0)).attr('x2',p.x(0)).attr('y1',p.m.top).attr('y2',p.h-p.m.bottom).attr('stroke',window.BookTheme.color('#eee7d6')).attr('stroke-opacity',.4);p.svg.style('cursor','crosshair').on('pointerdown',event=>{const [x,y]=d3.pointer(event);if(x>=p.m.left&&x<=p.w-p.m.right&&y>=p.m.top&&y<=p.h-p.m.bottom){state.epoch=p.x.invert(x);$('cosmo-epoch').value=state.epoch;save();components();}});
}
function refreshModel(){model=P.model(state.h0,state.matter);distanceSeries=d3.range(241).map(i=>P.distances(i/24,model));components();distance();}
bind('cosmo-h0','h0',refreshModel);bind('cosmo-matter','matter',refreshModel);bind('cosmo-epoch','epoch',components);
document.querySelectorAll('[data-epoch]').forEach(b=>b.addEventListener('click',()=>{state.epoch=b.dataset.epoch==='equality'?Math.log10(model.r/model.m):b.dataset.epoch==='future'?Math.log10(2):0;$('cosmo-epoch').value=state.epoch;save();components();}));$('model-reset').addEventListener('click',()=>{state.h0=70;state.matter=.3;state.epoch=0;$('cosmo-h0').value=70;$('cosmo-matter').value=.3;$('cosmo-epoch').value=0;save();refreshModel();});
function distance(){const v=P.distances(state.z,model);$('distance-z-value').textContent=fmt(state.z);$('distance-model').textContent=`沿用上方模型：H₀=${fmt(model.H0,0)} km/s/Mpc，Ωₘ,₀=${fmt(model.m)}，ΩΛ,₀=${fmt(model.l,5)}。`;
 for(const kind of ['dc','da','dl'])$('distance-'+kind).textContent=fmt(v[kind],1);$('emission-age').textContent=fmt(v.age,2)+' Gyr';$('today-age').textContent=fmt(v.t0,2)+' Gyr';$('lookback-time').textContent=fmt(v.lookback,2)+' Gyr';$('emission-marker').style.left=v.age/v.t0*100+'%';$('journey-remaining').style.width=v.lookback/v.t0*100+'%';
 const angle=20/(v.da*1000)*206264.806;$('distance-insight').textContent=`发光时 a=${fmt(v.a,3)}。若物理直径固定为 20 kpc，角直径为 ${fmt(angle,2)}″；总辐射面亮度为本征值的 1/${fmt(1/v.dim,1)}。这些量均假定源不演化、无消光。`;
 const selectedDistances=[...distanceSeries,v].sort((a,b)=>a.z-b.z);const kinds=state.kind==='all'?['dc','dl','da']:[state.kind],map={da:colors.r,dl:colors.m,dc:colors.l},top=d3.max(distanceSeries,d=>d3.max(kinds,k=>d[k]));const p=plot('distance-chart',d3.scaleLinear().domain([0,10]),d3.scaleLinear().domain([0,top*1.04]).nice(), '红移 z','距离 / Mpc');for(const k of kinds){BookCharts.addSeries(p.node,selectedDistances.map(d=>({x:d.z,y:d[k]})),{dc:'共动径向距离',dl:'光度距离',da:'角直径距离'}[k]);p.svg.append('path').datum(selectedDistances).attr('d',d3.line().x(d=>p.x(d.z)).y(d=>p.y(d[k]))).attr('fill','none').attr('stroke',map[k]).attr('stroke-width',2);p.svg.append('circle').attr('cx',p.x(state.z)).attr('cy',p.y(v[k])).attr('r',4).attr('fill',map[k]);}vertical(p,p.x(state.z));p.svg.style('cursor','crosshair').on('pointerdown',event=>{const [x,y]=d3.pointer(event);if(x>=p.m.left&&x<=p.w-p.m.right&&y>=p.m.top&&y<=p.h-p.m.bottom){state.z=Math.max(.01,Math.round(p.x.invert(x)*100)/100);$('distance-z').value=state.z;save();distance();}});
}
bind('distance-z','z',distance);$('distance-kind').addEventListener('change',e=>{state.kind=e.target.value;save();distance();});
function thermal(){const e=window.ThermalEpochs[state.thermal];$('thermal-tag').textContent=e.tag;$('thermal-title').textContent=e.title;$('thermal-body').textContent=e.body;$('thermal-detail').textContent=e.detail;$('thermal-source').textContent=e.source;$('thermal-symbol').dataset.glossaryContext=state.thermal===1?'thermal-nucleosynthesis':state.thermal===3?'thermal-recombination':'';$('thermal-symbol').textContent=e.symbol;document.querySelectorAll('[data-thermal]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.thermal===state.thermal)));const {c,ctx,w,h}=canvas('thermal-canvas');c.setAttribute('aria-label',e.name+'：粒子组成的定性示意，非按比例模拟。');const cy=(h-40)/2;
 function dot(x,y,r,col){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=col;ctx.fill();}
 for(let i=0;i<5;i++){const x=28+(i%3)*(w-56)/2,y=42+Math.floor(i/3)*(h-112);if(state.thermal===0){dot(x,y,5,colors.r);dot(x+12,y+6,4,colors.m);}else if(state.thermal<3){dot(x,y,5,colors.m);if(state.thermal===1&&i%2===0){dot(x+6,y,5,colors.r);dot(x+2,y+7,5,colors.m);}dot(x+18,y-14,2,colors.r);}else{dot(x,y,5,colors.m);ctx.strokeStyle=window.BookTheme.color('#56737a');ctx.beginPath();ctx.ellipse(x,y,16,9,-.4,0,Math.PI*2);ctx.stroke();dot(x+14,y-4,2,colors.r);}}
 for(let j=0;j<3;j++){const y=cy-20+j*23;ctx.strokeStyle=colors.r;ctx.lineWidth=1.2;ctx.beginPath();for(let x=15;x<w-15;x+=2){const yy=y+4*Math.sin((x+j*20)/(state.thermal===4?14:6));if(x===15)ctx.moveTo(x,yy);else ctx.lineTo(x,yy);}ctx.globalAlpha=.5;ctx.stroke();ctx.globalAlpha=1;}
}
window.ThermalEpochs.forEach((e,i)=>{const b=document.createElement('button');b.textContent=e.name;b.dataset.thermal=i;b.setAttribute('aria-pressed','false');b.addEventListener('click',()=>{state.thermal=i;save();thermal();});$('thermal-picker').append(b);});
function inflation(){const f=P.fluid(state.w,state.N);$('w-value').textContent=Math.abs(state.w-1/3)<.0005?'1/3':fmt(state.w,3);$('efolds-value').textContent=fmt(state.N,2);$('inflation-result').textContent=`尺度因子变为初值的 ${fmt(f.a,1)} 倍，共动哈勃尺度变为 ${f.hubbleRadius<.01?f.hubbleRadius.toExponential(2):fmt(f.hubbleRadius,3)} 倍。${f.accelerating?'当前为加速膨胀；共动哈勃尺度缩小。':Math.abs(state.w+1/3)<1e-10?'临界状态：共动哈勃尺度不变。':'当前为减速膨胀；共动哈勃尺度增大。'}`;document.querySelectorAll('[data-w]').forEach(b=>b.setAttribute('aria-pressed',String(Math.abs(+b.dataset.w-state.w)<1e-8)));
 const p=plot('inflation-chart',d3.scaleLinear().domain([0,6]),d3.scaleLog().domain([.001,1000]),'膨胀 e 折数 N','共动哈勃尺度 / 初值',7);p.svg.append('line').attr('x1',p.x(0)).attr('x2',p.x(6)).attr('y1',p.y(1)).attr('y2',p.y(1)).attr('stroke',window.BookTheme.color('#9caeac')).attr('stroke-dasharray','5 5');p.svg.append('text').attr('x',p.x(6)-3).attr('y',p.y(1)-8).attr('text-anchor','end').text('固定共动尺');const data=d3.range(121).map(i=>({x:i/20,y:P.fluid(state.w,i/20).hubbleRadius}));data.push({x:state.N,y:f.hubbleRadius});data.sort((a,b)=>a.x-b.x);BookCharts.addSeries(p.node,data,'共动哈勃尺度 / 初值');p.svg.append('path').datum(data).attr('d',d3.line().x(d=>p.x(d.x)).y(d=>p.y(d.y))).attr('fill','none').attr('stroke',colors.m).attr('stroke-width',2);vertical(p,p.x(state.N));p.svg.append('circle').attr('cx',p.x(state.N)).attr('cy',p.y(f.hubbleRadius)).attr('r',5).attr('fill',colors.m);
}
bind('fluid-w','w',inflation);bind('efolds','N',()=>{stop('inflation-play');inflation();});document.querySelectorAll('[data-w]').forEach(b=>b.addEventListener('click',()=>{state.w=+b.dataset.w;$('fluid-w').value=state.w;save();inflation();}));$('inflation-play').addEventListener('click',()=>animate('inflation-play','N','efolds',6,0,8000,inflation));
function tutor(text){window.showTutor('我在学习 Mo, van den Bosch & White (2010)《Galaxy Formation and Evolution》第3章。'+text+' 请解释物理含义、逐步推导相关关系，并区分教材依据、教学近似和额外解释；不要把这些示例参数当作最新观测结果。');}
$('tutor-open').addEventListener('click',()=>tutor('请围绕§3.1–3.6（pp.100–161），用尺度因子连接红移、距离、膨胀率与热历史，并设计一个理解检查问题。'));
$('expansion-question').addEventListener('click',()=>tutor(`依据§3.1 pp.102–112：a_emit=${fmt(state.a,3)}，a₀=1，z=${fmt(1/state.a-1,3)}；一格共动间隔100 Mpc，固有间隔${fmt(state.a*100,1)} Mpc。为何换一个共动观测者仍看到同样的膨胀？为何束缚星系不一起放大？`));
const modelPrompt=()=>`采用平直模型，H₀=${state.h0} km/s/Mpc，Ωm,0=${state.matter}，Ωr,0=0.00009，ΩΛ,0=${model.l.toFixed(5)}。辐射理想化为a⁻⁴。`;
$('components-question').addEventListener('click',()=>tutor(`依据§3.2 pp.113–120。${modelPrompt()}我选择a=${(10**state.epoch).toExponential(4)}，请解释占比、绝对密度、H与减速参数q的区别。`));
$('distance-question').addEventListener('click',()=>{const v=P.distances(state.z,model);tutor(`依据§3.1.6、§3.2.5–3.2.6 pp.110–112、119–124。${modelPrompt()}红移z=${state.z}，D_A=${fmt(v.da)} Mpc，D_L=${fmt(v.dl)} Mpc，D_C=${fmt(v.dc)} Mpc，回望时间${fmt(v.lookback)} Gyr。请检验距离互易关系，并解释角直径距离为何有峰值。假设透明传播、光子守恒，忽略K改正、透镜与源演化。`);});
$('thermal-question').addEventListener('click',()=>{const e=window.ThermalEpochs[state.thermal];tutor(`依据${e.source}，当前节点“${e.name}”。${e.body} 请解释其物理过程，指出与邻近阶段的区别。图解没有求解反应网络。`);});
$('inflation-question').addEventListener('click',()=>tutor(`依据§3.6 pp.152–161：平直、单一常数w流体，w=${state.w}，N=${fmt(state.N)}。请推导(aH)⁻¹相对初值的变化，区分哈勃尺度与粒子视界，并说明该模型缺少怎样的退出暴胀与再加热机制。`));
window.CosmoQuizzes.forEach(item=>{const row=document.createElement('article');row.className='quiz-item';const h=document.createElement('h3');h.textContent=item.q;const options=document.createElement('div');options.className='quiz-options';const feedback=document.createElement('p');feedback.className='quiz-feedback';feedback.setAttribute('aria-live','polite');item.options.forEach((option,i)=>{const b=document.createElement('button');b.textContent=option;b.setAttribute('aria-pressed','false');b.addEventListener('click',()=>{options.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));feedback.textContent=(i===item.answer?'正确。':'再想一步。')+item.why;});options.append(b);});row.append(h,options,feedback);$('cosmo-quiz').append(row);});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{expansion();components();distance();thermal();inflation();},100);});
expansion();refreshModel();thermal();inflation();
})();
